/*
 * SV-COMP compatibility shim for GenMC, for tasks that include <pthread.h>.
 * (Preprocessed tasks that declare the pthread API themselves use
 * svcomp-shim-pp.h plus a tail generated by svcomp-run.py.)
 *
 * Compile a task with: -include svcomp-shim.h. The shim renames the task's
 * main and its __VERIFIER_nondet_* calls with #defines, since GenMC passes
 * -D flags through the shell unquoted. Nondeterminism, atomic sections and
 * main are handled in svcomp-shim-core.h. The shim must not define what
 * GenMC's pthread.h defines, such as pthread_once; scripts/check-svcomp-shim.sh
 * builds tasks with it.
 *
 * - pthread_cond_wait: GenMC's pthread.h models condition variables, but its
 *   wait only returns after a signal or broadcast. Here a wait may also
 *   return without any signal (see svcomp-shim-core.h).
 * - Recursive mutexes: with SVC_RECURSIVE_MUTEX=1 (svcomp-run.py sets it
 *   when the task mentions PTHREAD_MUTEX_RECURSIVE), a mutex initialised
 *   with that type keeps an owner and a count around GenMC's mutex.
 * - malloc/calloc: GenMC's stdlib.h asserts that the size is not zero, which
 *   reports legal malloc(0) calls as safety violations. Here an execution
 *   that allocates zero bytes is discarded instead. They may fail (see
 *   svcomp-shim-core.h).
 * - abort(): SV-COMP uses it to cut off paths it is not interested in
 *   (assume_abort_if_not()). GenMC's interpreter calls the real abort(), which
 *   kills GenMC; here it discards the execution instead.
 * - pthread_detach, pthread_mutexattr_*, PTHREAD_RWLOCK_INITIALIZER: missing
 *   from GenMC's pthread.h; trivial versions here.
 * - scanf(fmt, p): missing from GenMC's stdio.h; stores a nondet value.
 */
#include <stdatomic.h>
#include <stdbool.h>
#include <stdlib.h>
#include <pthread.h>
#include <genmc.h>

#include "svcomp-shim-core.h"

static void *__svc_malloc(size_t n)
{
	__VERIFIER_assume(n > 0);
	return __svc_malloc_fails() ? NULL : __VERIFIER_malloc(n);
}

static void *__svc_calloc(size_t n, size_t sz)
{
	__VERIFIER_assume(n > 0 && sz > 0);
	return __svc_malloc_fails() ? NULL : __VERIFIER_calloc(n, sz);
}

static void __svc_abort(void)
{
	__svc_abort_path();
}

int pthread_detach(pthread_t t) { return 0; }
int pthread_mutexattr_init(pthread_mutexattr_t *a) { *a = 0; return 0; }
int pthread_mutexattr_destroy(pthread_mutexattr_t *a) { return 0; }
int pthread_mutexattr_settype(pthread_mutexattr_t *a, int kind) { *a = kind; return 0; }
#ifndef PTHREAD_RWLOCK_INITIALIZER
# define PTHREAD_RWLOCK_INITIALIZER { 0 }
#endif

#if SVC_RECURSIVE_MUTEX
/* Recursive mutexes, registered by pthread_mutex_init. owner is the owning
 * thread's id plus one; only the owner writes its own id, so a thread that
 * reads its own id holds the mutex. */
# define SVC_MAX_RECURSIVE 4

static struct {
	pthread_mutex_t *m;
	atomic_long owner;
	int count;
} __svc_rec[SVC_MAX_RECURSIVE];
static atomic_int __svc_nrec;

static int __svc_rec_find(pthread_mutex_t *m)
{
	int n = atomic_load_explicit(&__svc_nrec, memory_order_acquire);

	for (int i = 0; i < n; i++)
		if (__svc_rec[i].m == m)
			return i;
	return -1;
}

static int __svc_mutex_init(pthread_mutex_t *m, const pthread_mutexattr_t *a)
{
	if (a && *a == PTHREAD_MUTEX_RECURSIVE && __svc_rec_find(m) < 0) {
		int n = atomic_load_explicit(&__svc_nrec, memory_order_relaxed);

		__VERIFIER_assume(n < SVC_MAX_RECURSIVE);
		__svc_rec[n].m = m;
		atomic_store_explicit(&__svc_nrec, n + 1, memory_order_release);
	}
	return pthread_mutex_init(m, 0);
}

static int __svc_mutex_lock(pthread_mutex_t *m)
{
	int r = __svc_rec_find(m);
	long self = (long) pthread_self() + 1;

	if (r < 0)
		return pthread_mutex_lock(m);
	if (atomic_load_explicit(&__svc_rec[r].owner, memory_order_relaxed) == self) {
		__svc_rec[r].count++;
		return 0;
	}
	pthread_mutex_lock(m);
	atomic_store_explicit(&__svc_rec[r].owner, self, memory_order_relaxed);
	__svc_rec[r].count = 1;
	return 0;
}

static int __svc_mutex_unlock(pthread_mutex_t *m)
{
	int r = __svc_rec_find(m);

	if (r < 0)
		return pthread_mutex_unlock(m);
	if (--__svc_rec[r].count > 0)
		return 0;
	atomic_store_explicit(&__svc_rec[r].owner, 0, memory_order_relaxed);
	return pthread_mutex_unlock(m);
}
#endif

/* condition variables: GenMC's pthread.h models them, but its wait only
 * returns after a signal or broadcast. SV-COMP also allows spurious wakeups */
static int __svc_cond_wait(pthread_cond_t *c, pthread_mutex_t *m)
{
	unsigned int seq = __atomic_load_n(&c->__seq, __ATOMIC_ACQUIRE);
	int spurious = __svc_spurious_wakeup();

	pthread_mutex_unlock(m);
	if (!spurious)
		__VERIFIER_await(__atomic_load_n(&c->__seq, __ATOMIC_ACQUIRE) != seq);
	pthread_mutex_lock(m);
	return 0;
}
#define pthread_cond_wait(c, m) __svc_cond_wait(c, m)

/* scanf(fmt, p): GenMC's stdio.h has none; a task reads one number with it,
 * which is a nondet value here */
#define scanf(fmt, p) (*(p) = __svc_nondet_val(), 1)

/* GenMC's pthread_create, with an atomic store of the ID, which
 * svcomp-run.py tells from the task's own stores (see create_race()) */
static int __svc_pthread_create(pthread_t *t, const pthread_attr_t *a,
				void *(*fn)(void *), void *arg)
{
	__atomic_store_n(t, __VERIFIER_thread_create(a, fn, arg), __ATOMIC_RELAXED);
	return 0;
}
#define pthread_create __svc_pthread_create

#define malloc __svc_malloc
#define abort __svc_abort
#define calloc __svc_calloc
#if SVC_RECURSIVE_MUTEX
# define pthread_mutex_init __svc_mutex_init
# define pthread_mutex_lock __svc_mutex_lock
# define pthread_mutex_unlock __svc_mutex_unlock
#endif
